import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.5akMI7mQ.js";const g=JSON.parse('{"title":"Zero-Knowledge Encrypted Artifacts","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/zero-knowledge-artifacts.md","filePath":"core-concepts/zero-knowledge-artifacts.md","lastUpdated":1792429063000}'),r={name:"core-concepts/zero-knowledge-artifacts.md"};function i(o,e,l,c,p,d){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="zero-knowledge-encrypted-artifacts" tabindex="-1">Zero-Knowledge Encrypted Artifacts <a class="header-anchor" href="#zero-knowledge-encrypted-artifacts" aria-label="Permalink to &quot;Zero-Knowledge Encrypted Artifacts&quot;">​</a></h1><p>In multi-tenant serverless and distributed edge computing, hosting proprietary code and algorithms on third-party cloud infrastructure exposes developers to intellectual property leakage, reverse-engineering, and unauthorized host inspection.</p><p><strong>Wednes Serverless Engine</strong> adopts the <strong>Zero-Knowledge Encrypted Artifact</strong> paradigm: application code and compiled WebAssembly binaries remain encrypted throughout transit and storage, only being decrypted inside hardened, ephemeral memory boundaries during authorized execution.</p><hr><h2 id="the-core-problem" tabindex="-1">The Core Problem <a class="header-anchor" href="#the-core-problem" aria-label="Permalink to &quot;The Core Problem&quot;">​</a></h2><p>Traditional cloud functions upload raw JavaScript bundles, container images, or unencrypted binaries to cloud providers:</p><ol><li><strong>Host-Level Exposure:</strong> Cloud hypervisor operators, compromised nodes, or adjacent containers can inspect memory dumps and filesystem layers.</li><li><strong>Reverse Engineering:</strong> Proprietary trading logic, private API schemas, AI inference graphs, and confidential heuristics can be disassembled.</li><li><strong>Tampering:</strong> Malicious actors or compromised CI/CD runners can inject backdoors or alter bytecode without detection.</li></ol><hr><h2 id="architectural-pillars" tabindex="-1">Architectural Pillars <a class="header-anchor" href="#architectural-pillars" aria-label="Permalink to &quot;Architectural Pillars&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+───────────────────────────+</span></span>
<span class="line"><span>|   Developer Workstation   |</span></span>
<span class="line"><span>|   (Code + Private Keys)   |</span></span>
<span class="line"><span>+─────────────┬─────────────+</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              │ 1. Compile to WASM Component</span></span>
<span class="line"><span>              │ 2. Sign with Ed25519 Key</span></span>
<span class="line"><span>              │ 3. Encrypt payload (AES-256-GCM)</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>+───────────────────────────+</span></span>
<span class="line"><span>|   Encrypted Cloud Vault   |</span></span>
<span class="line"><span>| (Zero-Knowledge Storage)  |</span></span>
<span class="line"><span>|  - Restic AES-256 at Rest |</span></span>
<span class="line"><span>|  - Cloudflare R2 / S3     |</span></span>
<span class="line"><span>|  - Zero Egress Recovery   |</span></span>
<span class="line"><span>+─────────────┬─────────────+</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              │ 4. Pull Encrypted Artifact (Zero-Egress)</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>+───────────────────────────+</span></span>
<span class="line"><span>|     wednesd Host Node     |</span></span>
<span class="line"><span>|  - Ephemeral Decryption   |</span></span>
<span class="line"><span>|  - In-Memory Verification |</span></span>
<span class="line"><span>|  - Linear Memory Sandbox  |</span></span>
<span class="line"><span>+───────────────────────────+</span></span></code></pre></div><h3 id="_1-cryptographic-signature-integrity" tabindex="-1">1. Cryptographic Signature &amp; Integrity <a class="header-anchor" href="#_1-cryptographic-signature-integrity" aria-label="Permalink to &quot;1. Cryptographic Signature &amp; Integrity&quot;">​</a></h3><p>Every artifact is signed at build time using asymmetric cryptographic keypairs (such as Ed25519). Before the <code>wednesd</code> daemon accepts an artifact during deployment:</p><ul><li>It checks cryptographic signatures against trusted public keys.</li><li>It verifies cryptographic hashes (SHA-256) to ensure the artifact has not been modified.</li><li>It validates the binary structure strictly against the <code>wednes:function@0.1.0</code> WIT contract.</li></ul><h3 id="_2-encryption-at-rest-offsite-cloud-vault" tabindex="-1">2. Encryption at Rest &amp; Offsite Cloud Vault <a class="header-anchor" href="#_2-encryption-at-rest-offsite-cloud-vault" aria-label="Permalink to &quot;2. Encryption at Rest &amp; Offsite Cloud Vault&quot;">​</a></h3><p>Artifacts stored in local registries or synchronized offsite use authenticated encryption:</p><ul><li><strong>AES-256-GCM / ChaCha20-Poly1305:</strong> Artifact contents are encrypted at rest.</li><li><strong>Wednes Cloud Vault:</strong> Disaster recovery and multi-region deployment integrate with automated offsite vaults (via Restic with AES-256 encryption streaming to S3/Cloudflare R2 buckets with zero egress fees).</li></ul><h3 id="_3-ephemeral-in-memory-execution" tabindex="-1">3. Ephemeral In-Memory Execution <a class="header-anchor" href="#_3-ephemeral-in-memory-execution" aria-label="Permalink to &quot;3. Ephemeral In-Memory Execution&quot;">​</a></h3><p>When <code>wednesd</code> loads a zero-knowledge artifact:</p><ul><li>The binary is decrypted directly into memory buffers; decrypted bytecode is never written to disk in unencrypted format.</li><li>The Cranelift JIT engine compiles the component into native machine code held exclusively in protected executable memory pages.</li><li>Memory isolation prevents adjacent tenant processes or guest components from reading raw bytecode.</li></ul><hr><h2 id="security-guarantees-boundaries" tabindex="-1">Security Guarantees &amp; Boundaries <a class="header-anchor" href="#security-guarantees-boundaries" aria-label="Permalink to &quot;Security Guarantees &amp; Boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Guarantee</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Confidentiality at Rest</strong></td><td style="text-align:left;">Stored <code>.wasm</code> binaries cannot be inspected without the decryption key.</td></tr><tr><td style="text-align:left;"><strong>Tamper Detection</strong></td><td style="text-align:left;">Any modification to ciphertext causes immediate authentication tag verification failure.</td></tr><tr><td style="text-align:left;"><strong>No Ambient Host Leakage</strong></td><td style="text-align:left;">Guest instances cannot access host environment variables, encryption keys, or peer memory buffers.</td></tr><tr><td style="text-align:left;"><strong>Zero-Egress Vault Sync</strong></td><td style="text-align:left;">Synchronizing snapshots across regions or rebuilding failed nodes incurs $0 egress fee using zero-egress vaults.</td></tr></tbody></table><hr><h2 id="best-practices-for-operators" tabindex="-1">Best Practices for Operators <a class="header-anchor" href="#best-practices-for-operators" aria-label="Permalink to &quot;Best Practices for Operators&quot;">​</a></h2><ol><li><strong>Keep Private Keys Offline:</strong> Never bake deployment signing keys or master decryption keys into the guest function bytecode.</li><li><strong>Use Ephemeral Disks for Node Registries:</strong> Configure <code>registry.json</code> and artifact directories on encrypted filesystems (e.g., LUKS / dm-crypt or RAM-backed <code>tmpfs</code>).</li><li><strong>Rotate Operator Keys Regularly:</strong> Maintain a strict key rotation policy for CI/CD signing keys and registry tokens.</li></ol>`,25)])])}const h=t(r,[["render",i]]);export{g as __pageData,h as default};
